// Extraer resultados de las 3 consultas
const ventas = $('Consultar Ventas del Día').first().json;
const gastos = $('Consultar Gastos del Día').first().json;
const stockItems = $('Consultar Stock Bajo').all().map(item => item.json);

const fechaHoy = new Date().toLocaleDateString('es-ES', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const formatearDinero = (monto) => {
  return Number(monto || 0).toLocaleString('es-CL', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
};

let stockTexto = "";
if (stockItems.length === 0 || !stockItems[0].nombre) {
  stockTexto = "✅ ¡Todo el inventario está en niveles óptimos!\n";
} else {
  stockTexto = stockItems.map(p => `• <b>${p.nombre}</b> (Cód: <code>${p.codigo || 'S/C'}</code>) ➡️ <b>${p.stock_actual}</b> un.`
  ).join("\n") + "\n";
}

const totalVentas = Number(ventas.total_vendido || 0);
const totalGastos = Number(gastos.total_gastos || 0);
const balanceNeto = totalVentas - totalGastos;

const mensaje = `📊 <b>REPORTE DIARIO DE CIERRE - GDA POS</b>\n` +
`📅 <i>${fechaHoy}</i>\n\n` +
`━━━━━━━━━━━━━━━━━━\n` +
`💰 <b>RESUMEN FINANCIERO</b>\n` +
`• <b>Total Ventas:</b> $${formatearDinero(totalVentas)} (${ventas.total_operaciones || 0} tickets)\n` +
`• <b>Total Gastos:</b> -$${formatearDinero(totalGastos)} (${gastos.cantidad_gastos || 0} registros)\n` +
`• <b>Balance Neto:</b> <b>$${formatearDinero(balanceNeto)}</b>\n\n` +
`💳 <b>DESGLOSE DE MEDIOS DE PAGO</b>\n` +
`💵 Efectivo: $${formatearDinero(ventas.total_efectivo)}\n` +
`💳 Tarjetas: $${formatearDinero(ventas.total_tarjeta)}\n` +
`📲 Transferencias: $${formatearDinero(ventas.total_transferencia)}\n` +
(Number(ventas.total_otros) > 0 ? `🔄 Otros: $${formatearDinero(ventas.total_otros)}\n` : '') +
`\n━━━━━━━━━━━━━━━━━━\n` +
`⚠️ <b>PRODUCTOS CON STOCK CRÍTICO (≤ 5 un.)</b>\n` +
stockTexto +
`━━━━━━━━━━━━━━━━━━\n` +
`🤖 <i>Generado automáticamente por n8n & GDA POS</i>`;

return [{ json: { mensaje, fecha: fechaHoy } }];
